css:
.dcw-split.is-reverse { grid-template-columns: 7fr 5fr; align-items: center; }
.dcw-p.is-sm { font-size: 15px; line-height: 1.6; margin-bottom: 0; }
.dcw-tag { display: inline-block; margin-bottom: 14px; padding: 4px 12px; border-radius: 999px; background-color: #e3f2ef; color: #0a524e; font-size: 12px; font-weight: 600; letter-spacing: 0.04em; text-transform: uppercase; }
.dcw-li.is-sm { font-size: 14.5px; }
.dcw-artifact { padding: clamp(16px, 2.5vw, 28px); border: 1px solid #e2e2e2; border-radius: 16px; background-color: #ffffff; }
.dcw-board-img { display: block; width: 100%; aspect-ratio: 16 / 10; object-fit: cover; border-radius: 8px; }
.dcw-numbered { display: flex; flex-direction: column; }
.dcw-num-item { display: flex; grid-column-gap: 22px; padding-top: 20px; padding-bottom: 20px; border-top: 1px solid #e2e2e2; }
.dcw-num-n { flex: none; width: 28px; padding-top: 2px; color: #0f6e68; font-family: Inconsolata, monospace; font-size: 14px; }
.dcw-num-h { margin-top: 0; margin-bottom: 6px; color: #111111; font-size: 17px; font-weight: 600; line-height: 1.35; }
.dcw-goals { display: grid; grid-template-columns: repeat(4, 1fr); grid-column-gap: 14px; grid-row-gap: 14px; margin-top: 20px; }
.dcw-goal { display: flex; flex-direction: column; grid-row-gap: 14px; padding: 20px 20px 18px; border: 1px solid #e2e2e2; border-radius: 14px; background-color: #ffffff; box-shadow: 0 1px 2px rgba(6,43,42,0.05), 0 12px 28px -18px rgba(6,43,42,0.35); }
.dcw-goal-num { padding-bottom: 12px; border-bottom: 1px solid #e2e2e2; color: #0f6e68; font-family: Inconsolata, monospace; font-size: 13px; font-weight: 700; }
.dcw-goal-text { flex: 1; color: #111111; font-size: 16px; font-weight: 600; line-height: 1.45; }
.dcw-stats { display: grid; grid-template-columns: repeat(auto-fit, minmax(110px, 1fr)); grid-column-gap: 16px; grid-row-gap: 16px; width: 100%; margin-top: 20px; }
.dcw-stat { padding-top: 14px; border-top: 3px solid #0f6e68; }
.dcw-stat-n { color: #0f6e68; font-family: Poppins, sans-serif; font-size: clamp(32px, 3.6vw, 44px); font-weight: 700; line-height: 1.05; white-space: nowrap; }
.dcw-stat-l { margin-top: 4px; color: #5f5f5f; font-size: 14px; }
.dcw-words { display: flex; flex-wrap: wrap; grid-column-gap: 6px; grid-row-gap: 6px; }
.dcw-word { padding: 3px 9px; border: 1px solid #c9c9c9; border-radius: 4px; background-color: #fff8c9; color: #3d3d3d; font-size: 13px; }
.dcw-word.is-illegible { border-style: dashed; background-color: #ffffff; color: #5f5f5f; font-style: italic; }
.dcw-findings { display: flex; flex-direction: column; margin-top: 16px; }
.dcw-finding { display: grid; grid-template-columns: 1fr 1fr; grid-column-gap: 40px; grid-row-gap: 8px; padding-top: 22px; padding-bottom: 22px; border-top: 1px solid #e2e2e2; }
.dcw-finding-what { position: relative; padding-left: 20px; color: #111111; font-size: 17px; font-weight: 600; line-height: 1.45; }
.dcw-finding-dot { position: absolute; left: 0; top: 9px; width: 8px; height: 8px; border-radius: 50%; background-color: #0f6e68; }
.dcw-finding-so { color: #3d3d3d; font-size: 15px; line-height: 1.55; }
.dcw-finding-k { margin-bottom: 4px; color: #0f6e68; font-size: 11px; font-weight: 700; letter-spacing: 0.1em; text-transform: uppercase; }
.dcw-ia { display: grid; grid-template-columns: repeat(3, 1fr); grid-column-gap: 16px; grid-row-gap: 16px; margin-bottom: 12px; }
.dcw-ia-col { padding: 16px; border: 1px solid #e2e2e2; border-radius: 12px; background-color: #ffffff; }
.dcw-ia-root { margin-bottom: 10px; padding-bottom: 10px; border-bottom: 3px solid #0f6e68; color: #111111; font-weight: 700; }
.dcw-ia-item { padding: 6px 0 6px 14px; border-left: 1px solid #c9c9c9; color: #3d3d3d; font-size: 15px; }
.dcw-ia-empty { color: #5f5f5f; font-size: 14px; }
@media screen and (max-width: 991px) { .dcw-split.is-reverse { grid-template-columns: 1fr; } .dcw-goals { grid-template-columns: repeat(2, 1fr); } }
@media screen and (max-width: 767px) { .dcw-finding { grid-template-columns: 1fr; } .dcw-ia { grid-template-columns: 1fr; } .dcw-goals { grid-template-columns: 1fr; } }
